// Cités comme mixtes par Gabriel le 13/11 (« Camille, Dominique, Claude, Ilhan… ») : Ilhan est pourtant masculin à 100 % dans le
// fichier de l'Insee (4 715 naissances) ; on suit Gabriel, la civilité reste inconnue.
const DOUTEUX = new Set(['ilhan']);
export const normaliserPrenom = (p) => String(p || '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase().replace(/[^a-z' -]/g, '').replace(/[ ']+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
// 'M.', 'Mme' ou null. Un prénom composé absent de la table (« Alon-Emmanuel ») se lit sur son premier prénom.
export function civiliteDuPrenom(prenom) {
  const p = normaliserPrenom(prenom);
  if (!p || DOUTEUX.has(p)) return null;
  for (const k of [p, p.split('-')[0]]) {
    if (DOUTEUX.has(k)) return null;
    if (MASCULINS.has(k)) return 'M.';
    if (FEMININS.has(k)) return 'Mme';
  }
  return null;
}
